keys={'Everyday men':['everyday t shirts for men','plain t shirts men','cotton t shirts men','mens casual t shirts','mens crew neck t shirts','basic t shirts men','neutral t shirts men','black everyday t shirt','mens relaxed t shirts','minimal t shirts men'], 'Everyday women':['everyday t shirts women','plain t shirts women','cotton t shirts women','womens casual t shirts','womens crew neck tee','basic tees women','neutral t shirts women','sage green t shirt women','womens relaxed t shirts','minimal tees women'], 'Oversized':['oversized t shirts men','oversized t shirts women','plain oversized t shirt','oversized cotton tee','black oversized t shirt','sage oversized t shirt','oversized crew neck tee','oversized tshirt India','relaxed streetwear tee','how to style oversized tees']}
