for group,items in keys.items():
 for i,k in enumerate(items):keywords.append({'keyword':k,'group':group,'intent':'Informational' if k.startswith('how') else 'Commercial','use':'SEO article' if k.startswith('how') else 'SEO + proposed search ad','match':'Not an ad keyword' if k.startswith('how') else 'Exact' if i%2==0 else 'Phrase','page':'/journal.html' if k.startswith('how') else '/drop.html','volume':'Not measured','priority':'Test first' if i<3 else 'Explore later'})
rsas=[]
for group in keys:
 group_headlines=headlines.copy()
 group_headlines[2]={'Everyday men':'Everyday T-Shirts For Men','Everyday women':'Everyday T-Shirts For Women','Oversized':'Oversized T-Shirt Concepts'}[group]
 group_headlines[3]={'Everyday men':'Explore Men’s Everyday Fits','Everyday women':'Explore Women’s Everyday Fits','Oversized':'Find Your Relaxed Silhouette'}[group]
 for i,h in enumerate(group_headlines):rsas.append({'ad_group':group,'asset_type':'Headline','position':i+1,'text':h,'characters':len(h),'limit':30})
 for i,d in enumerate(descriptions):rsas.append({'ad_group':group,'asset_type':'Description','position':i+1,'text':d,'characters':len(d),'limit':90})
assert all(r['characters']<=r['limit'] for r in rsas)
